import requests

def test_425_too_early():
    assert requests.codes.too_early == 425
    assert requests.codes.TOO_EARLY == 425
    assert requests.codes['too_early'] == 425
    assert requests.codes['TOO_EARLY'] == 425

if __name__ == "__main__":
    try:
        test_425_too_early()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        exit(1)
